'use strict';

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pinoHttp = require('pino-http');

const app = express();

// ---------------------
// Basic security hardening
// ---------------------
app.disable('x-powered-by');
app.use(helmet());                                 // security headers
app.use(cors({ origin: process.env.ALLOWED_ORIGIN || 'https://your-frontend.example.com' }));
app.use(express.json({ limit: '100kb' }));         // body‑size limit
app.use(pinoHttp());                               // request logging

// Rate limiting – applies globally; tweak per‑route if needed
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                 // limit each IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests' }
});
app.use(limiter);

// ---------------------
// Routes
// ---------------------
app.get('/health', (req, res) => {
  // Minimal health payload – no timestamps to avoid info leakage
  res.json({ status: 'ok' });
});

app.get('/users', (req, res) => {
  // In a real app this would come from a DB with parameterised queries
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ]);
});

// ---------------------
// Error handling (must be after all routes)
// ---------------------
app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// ---------------------
// Server start – respect PORT env var and support HTTPS via proxy
// ---------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

