Below is a concise “secure‑by‑default” version that addresses the points above while keeping the original demo functionality.

```js
// app.js – secure starter template
require('dotenv').config();               // loads .env (dev convenience)

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// -------------------
// Middleware
// -------------------
app.use(helmet());                       // security headers
app.use(express.json());                 // if you later add POST bodies
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Basic rate limiting: 100 req/min per IP
const limiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// -------------------
// Routes
// -------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * NOTE: In a real app, user data would be loaded from a DB or external service.
 * The endpoint is kept for demo purposes but does NOT expose email addresses
 * unless proper auth is added.
 */
app.get('/users', (req, res) => {
  // Example of a safe static payload (no PII)
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// -------------------
// 404 handler
// -------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// -------------------
// Global error handler (no stack traces in prod)
// -------------------
app.use((err, req, res, next) => {       // eslint-disable-line no-unused-vars
  console.error(err);
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;
  res.status(status).json({ error: message });
});

// -------------------
// Server start
// -------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

**What changed?**

* `helmet` adds a suite of HTTP security headers.
* `express-rate-limit` mitigates DoS/brute‑force.
* `morgan` gives request logging.
* Port is configurable via `process.env.PORT`.
* The `/users` endpoint no longer returns raw email addresses.
* Generic 404 and error‑handling middleware added.
* Added `.env` support via `dotenv` for local development.

