// app.js – hardened version
'use strict';

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// -------------------
// Security middleware
// -------------------
app.use(helmet());               // Sets common security headers
app.use(cors({                   // Adjust origins for your real UI
  origin: ['https://my‑app.com'],
  methods: ['GET'],
}));
// Simple rate limiter (adjust limits to your traffic profile)
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,            // max 100 requests per minute per IP
});
app.use(limiter);

// -------------------
// Routes
// -------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app replace this static array with a DB call.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// --------------
// Error handling
// --------------
app.use((err, _req, res, _next) => {
  console.error(err); // log internally
  res.status(500).json({ error: 'Internal Server Error' });
});

// ----------------
// Server start
// ----------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, '127.0.0.1', () => {
  console.log(`Server running on http://127.0.0.1:${PORT}`);
});

module.exports = app;
```

