require('dotenv').config();          // loads .env (dev only)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------- Security middlewares ----------
app.use(helmet());
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' })); // tighten in prod
app.use(express.json({ limit: '10kb' }));

// Simple rate limiter (adjust for your traffic)
