    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// ---------- Server ----------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
server.on('error', (err) => {
  console.error('Server start error:', err);
  process.exit(1);
});

module.exports = app;
```

