## 4. Quick “Hardening” Patch (example)

Below is a minimal patch you could apply to `app.js` that addresses many of the above concerns without changing the core behaviour:

```js
// app.js – hardened version
'use strict';

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middlewares
app.use(helmet());                     // Secure HTTP headers
app.use(cors({ origin: '*'}));         // Adjust origin list for production
app.use(morgan('combined'));           // Request logging
app.use(express.json());               // Body parser (future routes)

// Rate limiting – 100 req / 15 min per IP (tune as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health endpoint – minimal info
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint – static data (kept as‑is)
app.get('/users', (_req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Generic error handler (catch‑all)
app.use((err, _req, res, _next) => {
  console.error(err);                 // Log stack trace to server logs
  res.status(500).json({ error: 'Internal Server Error' });
});

// Listen – respect PORT env var (use 3000 as fallback)
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

> **Note:** The above patch introduces new dependencies (`helmet`, `cors`, `morgan`, `express-rate-limit`). Add them to `package.json` and run `npm install`. Adjust the CORS configuration and rate‑limit settings for your actual threat model.

